function e($s){return htmlspecialchars((string)$s,ENT_QUOTES,'UTF-8');}function now(){return gmdate('c');}function p($k,$d=''){return trim((string)($_POST[$k]??$d));}function csrf(){if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(32));return $_SESSION['csrf'];}function token(){echo '<input type="hidden" name="csrf" value="'.e(csrf()).'">';}function checkcsrf(){if($_SERVER['REQUEST_METHOD']==='POST'&&!hash_equals($_SESSION['csrf']??'',$_POST['csrf']??'')){http_response_code(400);exit('Invalid CSRF token.');}}
function satbtc($s){return number_format(((int)$s)/100000000,8,'.','');}function btcsat($b){return (int)round(((float)$b)*100000000);}function price_usd(){global $config;$file=$config['price_cache'];$cached=is_file($file)?json_decode(file_get_contents($file),true):null;if(is_array($cached)&&isset($cached['usd'],$cached['time'])&&time()-$cached['time']<120)return (float)$cached['usd'];$ctx=stream_context_create(['http'=>['timeout'=>4,'header'=>'Accept: application/json\r\n']]);$raw=@file_get_contents('https://api.coingecko.com/api/v3/simple/price?ids=bitcoin&vs_currencies=usd&include_last_updated_at=true',false,$ctx);$usd=0;if($raw){$j=json_decode($raw,true);$usd=(float)($j['bitcoin']['usd']??0);}if($usd>0){file_put_contents($file,json_encode(['usd'=>$usd,'time'=>time()],JSON_PRETTY_PRINT),LOCK_EX);return $usd;}return is_array($cached)&&isset($cached['usd'])?(float)$cached['usd']:0;}function usd_sat($usd){$p=price_usd();return $p>0?(int)round(((float)$usd/$p)*100000000):0;}function satusd($sat){$p=price_usd();return $p>0?(((int)$sat)/100000000)*$p:0;}function usd($n){return number_format((float)$n,2,'.',',');}
