function b32e($d){$a='ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';$bits='';$o='';for($i=0;$i<strlen($d);$i++)$bits.=str_pad(decbin(ord($d[$i])),8,'0',STR_PAD_LEFT);foreach(str_split($bits,5) as $c){if(strlen($c)<5)$c=str_pad($c,5,'0');$o.=$a[bindec($c)];}return $o;}function b32d($b){$a='ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';$b=strtoupper(preg_replace('/[^A-Z2-7]/','',$b));$bits='';$o='';for($i=0;$i<strlen($b);$i++){ $v=strpos($a,$b[$i]);if($v!==false)$bits.=str_pad(decbin($v),5,'0',STR_PAD_LEFT);}foreach(str_split($bits,8) as $c)if(strlen($c)===8)$o.=chr(bindec($c));return $o;}function secret(){return b32e(random_bytes(20));}function totp($sec,$time=null){$time=$time??time();$ctr=floor($time/30);$hash=hash_hmac('sha1',pack('N*',0).pack('N*',$ctr),b32d($sec),true);$off=ord(substr($hash,-1))&15;$v=((ord($hash[$off])&127)<<24)|(ord($hash[$off+1])<<16)|(ord($hash[$off+2])<<8)|ord($hash[$off+3]);return str_pad($v%1000000,6,'0',STR_PAD_LEFT);}function valid_totp($sec,$c){$c=preg_replace('/\D/','',$c);for($i=-1;$i<=1;$i++)if(hash_equals(totp($sec,time()+$i*30),$c))return true;return false;}
